INSERT INTO phases (id, term, title, weeks, description, tags, hue, sort_order) VALUES
  (1, 'فاز ۱', 'پی‌ریزی: برنامه‌نویسی مقدماتی', 8, 'اولین خطوط کد را با پایتون می‌نویسی و با ترمینال، لینوکس و Git آشنا می‌شو؛ ابزارهایی که هر روزِ یک مهندس را می‌سازند.', ARRAY['مبانی پایتون', 'اوبونتو، لینوکس و Git', 'وایب کدینگ با AI'], 'teal', 1),
  (2, 'فاز ۲', 'شی‌گرایی و ساختمان داده‌ها', 10, 'تفکر شی‌گرا را با جاوا تمرین می‌کنی و ساختمان داده‌ای کلیدی را پیاده‌سازی می‌کنی تا کدت ساختار پیدا کند.', ARRAY['شی‌گرایی جاوا', 'ساختمان داده‌ها', 'پروژه کتابخانه'], 'amber', 2),
  (3, 'فاز ۳', 'عمق علوم کامپیوتر', 12, 'الگوریتم‌های پیشرفته، سیستم‌عامل و شبکه؛ همان چیزی که مهندسان خودساخته را از کدنویس‌ها جدا می‌کند.', ARRAY['الگوریتم پیشرفته', 'سیستم‌عامل', 'شبکه'], 'cyan', 3),
  (4, 'فاز ۴', 'مهندسی نرم‌افزار کلاسیک', 8, 'چرخه حیات، نیازمندی‌ها و مدل‌سازی UML را یاد می‌گیری و اولین سیستم واقعی را روی کاغذ طراحی می‌کنی.', ARRAY['مهندسی نرم‌افزار', 'UML', 'پایگاه داده'], 'coral', 4),
  (5, 'فاز ۵', 'طراحی حرفه‌ای و کیفیت', 8, 'الگوهای طراحی و TDD؛ از اینجا به بعد کدی می‌نویسی که هم‌تیمی‌ها دوستش دارند و تغییرش نمی‌ترساند.', ARRAY['الگوهای طراحی', 'تست و TDD', 'کد تمیز'], 'teal', 5),
  (6, 'فاز ۶', 'توسعه وب فول‌استک', 12, 'با مفاهیم عمیق وب، React و Node.js یک محصول واقعی از دیتابیس تا رابط کاربری می‌سازی و دیپلوی می‌کنی.', ARRAY['مفاهیم وب و رندر', 'React', 'Node.js', 'REST API'], 'amber', 6),
  (7, 'فاز ۷', 'معماری و سیستم‌های توزیع‌شده', 10, 'میکروسرویس‌ها، داکر و کوبرنتیز و اصول سیستم‌های توزیع‌شده؛ سیستم‌هایی که زیر بار میلیون‌ها کاربر خم نمی‌شوند.', ARRAY['معماری نرم‌افزار', 'Raft و CAP', 'Docker و K8s', 'سیستم‌های توزیع‌شده'], 'cyan', 7),
  (8, 'فاز ۸', 'پروژه پایانی و ورود به بازار کار', 6, 'پروژه جامع تیمی، مرور کد توسط منتور، ساخت رزومه مهندسی و شبیه‌سازی مصاحبه‌های فنی.', ARRAY['پروژه تیمی', 'Code Review', 'مصاحبه فنی'], 'coral', 8)
