INSERT INTO testimonials (id, text, name, role, stars) VALUES
  ('t1', 'بعد از دوره معماری نرم‌افزار، در مصاحبه فنی یک فین‌تک قبول شدم. سوالاتی که پرسیدند دقیقاً همان چیزهایی بود که دکتر کمالی در دوره باز کرده بود.', 'امیرحسین رضایی', 'مهندس بک‌اند · فین‌تک', 5),
  ('t2', 'مسیر یادگیری ترم‌بندی‌شده باعث شد از سردرگمی بیرون بیایم. می‌دانستم هر هفته چه چیزی یاد می‌گیرم و چرا.', 'مهسا کریمی', 'دانشجوی کامپیوتر · دانشگاه تهران', 5),
  ('t3', 'تمرین‌های دوره ساختمان داده واقعا چالشی بود. برای اولین بار احساس کردم مسئله‌حل‌کردن را یاد گرفته‌ام نه حفظ‌کردن.', 'پارسا نعمتی', 'توسعه‌دهنده نرم‌افزار', 5),
  ('t4', 'پروژه پایانی دوره فول‌استک را داخل رزومه‌ام گذاشتم و همان پروژه در سه مصاحبه موضوع اصلی صحبت بود.', 'الناز موسوی', 'فرانت‌اند دولوپر', 5),
  ('t5', 'کلاس‌های لایو کدریوی هر هفته نقطه قوت ماجراست. جایی که گیر می‌کنی، همان لحظه می‌پرسی و جلو می‌روی.', 'کیان مرادی', 'تغییر مسیر شغلی به برنامه‌نویسی', 4),
  ('t6', 'به‌عنوان یک مهندس با ۵ سال سابقه، دوره الگوهای طراحی دیدم را به کد خودم تغییر داد. حالا Refactor برایم ترسناک نیست.', 'شیرین احمدی', 'مهندس نرم‌افزار ارشد', 5)
INSERT INTO faqs (id, question, answer, sort_order) VALUES
  ('f1', 'هیچ پیش‌زمینه‌ای از برنامه‌نویسی ندارم؛ از کجا شروع کنم؟', 'از «مسیر یادگیری» شروع کن. فاز ۱ برای همین طراحی شده: مبانی پایتون + لینوکس و Git، بدون هیچ پیش‌نیازی. دوره پایتون هم کاملاً رایگان است تا بدون ریسک شروع کنی.', 1),
  ('f2', 'آیا بعد از پایان دوره گواهی صادر می‌شود؟', 'بله. با گذراندن حداقل ۸۰٪ جلسات و قبولی در پروژه پایانی، گواهی دیجیتال با کد یکتا دریافت می‌کنی که قابل استعلام و افزودن به لینکدین است.', 2),
  ('f3', 'دسترسی من به محتوای دوره چقدر است؟', 'دسترسی مادام‌العمر. هر آپدیتی که روی دوره منتشر شود هم بدون هزینه به کتابخانه‌ات اضافه می‌شود؛ چون مهندسی نرم‌افزار یک‌بار یاد گرفتن ندارد.', 3),
  ('f4', 'تمرین‌ها و پروژه‌ها چگونه بررسی می‌شوند؟', 'تمرین‌های کدبیس با تست خودکار سنجیده می‌شوند و پروژه‌ها توسط منتورهای انسانی Code Review می‌شوند — با کامنت‌های خط‌به‌خط، دقیقاً مثل یک تیم واقعی.', 4),
  ('f5', 'اگر از دوره راضی نبودم چه؟', 'تا ۷ روز بعد از خرید، بدون هیچ سوالی، کل مبلغ برگشت داده می‌شود. کیفیت آموزش برای ما شوخی نیست.', 5),
  ('f6', 'امکان بورسیه یا تخفیف دانشجویی هست؟', 'هر ترم ۱۰٪ از ظرفیت دوره‌ها به بورسیه دانشجویان مستعد اختصاص دارد. دانشجویان فعال هم با معدل بالای ۹۰ در تمرین‌ها، ۲۵٪ تخفیف دوره بعدی می‌گیرند.', 6)
